SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.base"."title" AS "title"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE ((("public"."article"."author_id") = (('3')::integer)) AND (("public"."article"."id") > (('1')::integer)))   ORDER BY "id" ASC NULLS LAST  ) AS "_root.base"    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"
